// Normalize ANY supported event source into one shape:
//   { id, title, description, severity, service, scope, category }
// CONFIG below maps services->scopes and keywords->skill categories.
const CFG = {
  serviceScopeMap: { 'default': 'data-team' },   // e.g. 'billing-api': 'engineering'
  categoryRules: [
    { re: /stream|kafka|pipeline/i, cat: 'streaming' },
    { re: /bill|invoice|payment/i, cat: 'billing' },
    { re: /auth|login|token/i, cat: 'auth' }
  ],
  repo: 'repo',            // git repo under workspace/ for the apply step
  base: 'main',
  applyVerify: 'npm test', // self-verify command for the fix worktree
  encodeLearning: true
};
const raw = $input.first().json;
const b = raw.body || raw;
let ev;
if (b.event && (b.event.event_type || b.event.eventType)) {
  // PagerDuty v3 webhook
  const d = b.event.data || {};
  ev = { title: d.title || b.event.event_type, description: JSON.stringify(d).slice(0, 1500),
         severity: d.urgency === 'high' ? 'error' : 'warn', service: d.service?.summary || 'default' };
} else if (Array.isArray(b.alerts)) {
  // Prometheus Alertmanager / Grafana
  const firing = b.alerts.filter(a => a.status === 'firing');
  const a0 = firing[0] || b.alerts[0] || {};
  ev = { title: a0.labels?.alertname || 'alert', description: firing.map(a => `${a.labels?.alertname}: ${a.annotations?.summary || a.annotations?.description || ''}`).join('\n').slice(0, 1500),
         severity: 'error', service: a0.labels?.service || a0.labels?.job || 'default' };
} else if (b.command || (b.event && b.event.type === 'app_mention')) {
  // Slack slash command (form fields) or Events-API mention
  const text = b.text || b.event?.text || '';
  ev = { title: `chat request: ${text.slice(0, 80)}`, description: text,
         severity: 'warn', service: 'default' };
} else {
  // generic { title, description, severity?, service? }
  ev = { title: b.title || 'incident', description: b.description || JSON.stringify(b).slice(0, 1500),
         severity: b.severity || 'warn', service: b.service || 'default' };
}
const hay = `${ev.title} ${ev.description}`;
const category = (CFG.categoryRules.find(r => r.re.test(hay)) || {}).cat || 'general';
const scope = CFG.serviceScopeMap[ev.service] || CFG.serviceScopeMap['default'];
return [{ json: { ...ev, id: `inc-${$execution.id}`, scope, category, cfg: CFG } }];

