// Build the approval request: apply the proposed fix, or stop at diagnosis?
const ev = $('Normalize + classify').first().json;
const r = $input.first().json;
const text = (r.result && (typeof r.result.result === 'string' ? r.result.result : JSON.stringify(r.result))) || '';
return [{ json: {
  title: `Apply proposed fix for ${ev.id}? (${ev.title})`,
  message: `Scope: ${ev.scope} | tier: ${r.decision?.tier} ${r.decision?.model}\nReport: deliverables/${ev.id}.md\n\n--- DIAGNOSIS (excerpt) ---\n${text.slice(0, 2500)}`,
  source: 'incident-responder',
  autoApprove: false
} }];

const ev = $('Normalize + classify').first().json;
const fan = $('Apply fix (worktree)').first().json;
const r = (fan.results || [])[0] || {};
return [{ json: {
  severity: r.verify?.passed ? 'info' : 'warn',
  title: `Incident ${ev.id}: fix ${r.verify?.passed ? 'ready for merge' : 'NEEDS ATTENTION'}`,
  message: `${fan.review || ''}\nBranch: ${r.branch || 'n/a'} | verify: ${r.verify ? (r.verify.passed ? 'PASS' : 'FAIL') : 'not run'}\nLearning encoded to skills/. Merge remains a human act.`,
  source: 'incident-responder'
} }];

const ev = $('Normalize + classify').first().json;
const gate = $('Request approval').first().json;
return [{ json: {
  severity: 'warn',
  title: `Incident ${ev.id}: diagnosis only (fix not applied)`,
  message: `${gate.timedOut ? 'Approval timed out — default deny.' : 'Fix rejected by approver.'}\nReport remains at deliverables/${ev.id}.md.`,
  source: 'incident-responder'
} }];
